from dataclasses import dataclass
import sys
import argparse
import logging
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional
from taf.config.scf.scf_operations import SCFOperations
from taf.internal.scf.exceptions import ScfCannotBeCreated


@dataclass
class BlacklistedParameter:
    feature_id: str
    query: Dict[str, Any]
    reason: str

BLACKLISTED_PARAMETERS = [BlacklistedParameter(feature_id='CB012788',
                                               query={'p_name': 'actAntiTheftProtectionSystem',
                                                      'dist_name': r'.*FEATCADM-.*',
                                                      'value': 'MCC only'},
                                               reason='Parameter `actAntiTheftProtectionSystem="MCC only"` enables Anti-Theft '
                                                        'Protection System which may lead to device lockout.\n'
                                                      '    For more info check: CB012788 (System Module Anti-Theft) feature.'),
                          BlacklistedParameter(feature_id='CB012788',
                                               query={'p_name': 'actAntiTheftProtectionSystem',
                                                      'dist_name': r'.*FEATCADM-.*',
                                                      'value': 'MCC and MNC'},
                                               reason='Parameter `actAntiTheftProtectionSystem="MCC and MNC"` enables Anti-Theft '
                                                        'Protection System which may lead to device lockout.\n'
                                                      '    For more info check: CB012788 (System Module Anti-Theft) feature.'),
                          BlacklistedParameter(feature_id='CB013048',
                                               query={'p_name': 'actRadioSecMarking',
                                                      'dist_name': r'.*FEATCADM-.*',
                                                      'value': 'MCC only'},
                                               reason='Parameter `actRadioSecMarking="MCC only"` enables Anti-Theft Protection '
                                                        'System which may lead to device lockout.\n'
                                                      '    For more info check: CB013048 (Radio Unit Anti-Theft) feature.'),
                          BlacklistedParameter(feature_id='CB013048',
                                               query={'p_name': 'actRadioSecMarking',
                                                      'dist_name': r'.*FEATCADM-.*',
                                                      'value': 'MCC and MNC'},
                                               reason='Parameter `actRadioSecMarking="MCC and MNC"` enables Anti-Theft Protection '
                                                        'System which may lead to device lockout.\n'
                                                      '    For more info check: CB013048 (Radio Unit Anti-Theft) feature.'),
                          ]


def _setup_logger() -> logging.Logger:
    """
    Configure a simple logger for CLI output.
    Sends messages to stdout with minimal formatting.
    """
    logger = logging.getLogger("taf.config.scf.hazard")
    if not logger.handlers:
        handler = logging.StreamHandler(stream=sys.stdout)
        handler.setFormatter(logging.Formatter("%(message)s"))
        logger.addHandler(handler)
    logger.setLevel(logging.INFO)
    return logger


def _iter_xml_files(paths: Iterable[str]) -> Iterable[str]:
    """
    Yield XML file paths from a mix of files/directories.
    Directories are searched recursively for "*.xml".
    """
    for p in paths:
        p_path = Path(p)
        if p_path.is_dir():
            for f in p_path.rglob("*.xml"):
                yield str(f)
        elif p_path.is_file() and p_path.suffix.lower() == ".xml":
            yield str(p_path)


def _collect_xml_files(paths: Iterable[str]) -> List[str]:
    """
    Expand input paths into a unique, sorted list of XML files.
    """
    return sorted(set(_iter_xml_files(paths)))


def _xml_is_valid_scf(scf: SCFOperations) -> bool:
    tag = scf._internal_scf._tree.tag
    tag_name = tag.split('}', maxsplit=1)[-1] if tag.startswith('{') else tag
    return tag_name == "raml"

def _parse_args(argv=None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        prog="taf.config.scf.hazard",
        description="Hazardous parameter checker CLI for SCF configuration files",
    )
    parser.add_argument(
        "scf_path",
        nargs="*",
        help="Paths to SCF XML files or directories to analyze",
    )
    return parser.parse_args(argv)


def _analyze_file(logger: logging.Logger, scf_file: str) -> bool:
    logger.info(f"\nAnalyzing SCF file: {scf_file}")
    try:
        violations = find_blacklisted_param(BLACKLISTED_PARAMETERS, scf_file)
    except (ScfCannotBeCreated, AttributeError) as e:
        logger.info(f" - Unable to read XML: {e}")
        return False
    if violations:
        for v in violations:
            logger.info(f" - {v}")
        return True
    return False


def _report_status(logger: logging.Logger, violations_found: bool) -> int:
    if violations_found:
        logger.info("\nStatus: HAZARDOUS FEATURES FOUND")
        return 1
    logger.info("\nStatus: OK")
    return 0


def _analyze_files(logger: logging.Logger, paths: Iterable[str]) -> int:
    input_files = _collect_xml_files(paths)
    if not input_files:
        logger.info("No SCF XML files found. Nothing to analyze.")
        return 0

    violations_found = False
    for scf_file in input_files:
        if _analyze_file(logger, scf_file):
            violations_found = True

    return _report_status(logger, violations_found)


def main(argv=None):
    """
    Hazardous features enabled in SCF - checker
    """
    args = _parse_args(argv)
    logger = _setup_logger()

    if not args.scf_path:
        logger.info("No SCF path provided. Nothing to analyze.")
        return 0

    return _analyze_files(logger, args.scf_path)

def find_blacklisted_param(blacklisted_parameters_list: Iterable[BlacklistedParameter], scf_file: str) -> List[str]:
    found_params: List[str] = []
    scf = SCFOperations()
    scf.load_scf(scf_file)
    if not _xml_is_valid_scf(scf):
        raise ScfCannotBeCreated(f"File {scf_file} is not a valid SCF XML.")
    for param in blacklisted_parameters_list:
        query = {k: v for k, v in param.query.items() if k != "value"}
        violation = scf.get_all_values_from_scf_by_pattern(**query)
        value: Optional[Any] = param.query.get("value")
        if violation and (value is None or value in violation):
            found_params.append(param.reason)
    return found_params


if __name__ == "__main__":
    sys.exit(main())
